  "Animals with tissues, 720 million years ago": { es: "Animales con tejidos, hace 720 millones de años", ar: "حيوانات ذات أنسجة، قبل 720 مليون سنة", zh: "有组织的动物，7.2亿年前", sw: "Wanyama wenye tishu, miaka milioni 720 iliyopita", sv: "Djur med vävnader, för 720 miljoner år sedan", de: "Gewebetiere, vor 720 Millionen Jahren", pt: "Animais com tecidos, há 720 milhões de anos", fr: "Animaux à tissus, il y a 720 millions d'années" },
