  "Vertebrates, 560 million years ago": { es: "Vertebrados, hace 560 millones de años", ar: "الفقاريات، قبل 560 مليون سنة", zh: "脊椎动物，5.6亿年前", sw: "Wanyama wenye uti wa mgongo, miaka milioni 560 iliyopita", sv: "Ryggradsdjur, för 560 miljoner år sedan", de: "Wirbeltiere, vor 560 Millionen Jahren", pt: "Vertebrados, há 560 milhões de anos", fr: "Vertébrés, il y a 560 millions d'années" },
  "Jawed vertebrates, 465 million years ago": { es: "Vertebrados con mandíbula, hace 465 millones de años", ar: "الفقاريات الفكّية، قبل 465 مليون سنة", zh: "有颌脊椎动物，4.65亿年前", sw: "Wanyama wenye uti wa mgongo na taya, miaka milioni 465 iliyopita", sv: "Käkförsedda ryggradsdjur, för 465 miljoner år sedan", de: "Kiefermäuler, vor 465 Millionen Jahren", pt: "Vertebrados com mandíbula, há 465 milhões de anos", fr: "Vertébrés à mâchoires, il y a 465 millions d'années" },
