  "glutamic acid": { es: "ácido glutámico", ar: "حمض الغلوتاميك", zh: "谷氨酸", sw: "asidi glutamiki", sv: "glutaminsyra", de: "Glutaminsäure", pt: "ácido glutâmico", fr: "acide glutamique" },
  "lysine": { es: "lisina", ar: "ليسين", zh: "赖氨酸", sw: "lisini", sv: "lysin", de: "Lysin", pt: "lisina", fr: "lysine" },
  "serine": { es: "serina", ar: "سيرين", zh: "丝氨酸", sw: "serini", sv: "serin", de: "Serin", pt: "serina", fr: "sérine" },
